"""Masked castle sprite matching, independent of map memory and game input.

Flags and known cursor cells are ignored. All other visible foreground pixels
must agree at >=94%; geometry is not guessed from one roof colour. The old
roof reader remains a fallback for clipped and otherwise unreadable sprites.
"""
from __future__ import annotations

import base64
from dataclasses import dataclass
from functools import lru_cache
import zlib

from docich.hanjuku_speedrun.hanjuku.os_layer.castle_data import LABELS, RGBA_B85
from docich.hanjuku_speedrun.hanjuku.os_layer.pixels import Frame, near_bits

WIDTH, HEIGHT = 48, 56
TOLERANCE = 8  # RGB565 truncation vs the core's bit-replicated RGB888 (0..7).
MIN_AGREEMENT = 94
MAX_CANDIDATES = 128


@dataclass(frozen=True)
class Template:
    kind: str
    level: int
    themes: tuple[int, ...]
    points: tuple
    box: tuple
    anchors: tuple


@lru_cache(maxsize=1)
def templates() -> tuple[Template, ...]:
    raw = zlib.decompress(base64.b85decode(RGBA_B85))
    assert len(raw) == len(LABELS) * WIDTH * HEIGHT * 4
    out = []
    for index, (kind, level, themes, flags, anchor_xy) in enumerate(LABELS):
        sprite = raw[index * WIDTH * HEIGHT * 4:(index + 1) * WIDTH * HEIGHT * 4]
        points = tuple((x, y, tuple(sprite[(y * WIDTH + x) * 4:(y * WIDTH + x) * 4 + 3]))
                       for y in range(HEIGHT) for x in range(WIDTH)
                       if sprite[(y * WIDTH + x) * 4 + 3] and (x // 8, y // 8) not in flags)
        xs, ys = [p[0] for p in points], [p[1] for p in points]
        # Four disjoint triples across the silhouette. Require two colours
        # per triple: one flat rock/shadow region must not propose a castle.
        by_xy = {(x, y): (x, y, colour) for x, y, colour in points}
        anchors = tuple(by_xy[xy] for xy in anchor_xy)
        out.append(Template(kind, level, tuple(themes), points,
                            (min(xs), min(ys), max(xs), max(ys)), tuple(anchors)))
    return tuple(out)


def _overlap(a, b):
    area = max(0, min(a[2], b[2]) - max(a[0], b[0]) + 1) * max(
        0, min(a[3], b[3]) - max(a[1], b[1]) + 1)
    smaller = min((a[2] - a[0] + 1) * (a[3] - a[1] + 1),
                  (b[2] - b[0] + 1) * (b[3] - b[1] + 1))
    return area * 2 > smaller


def match_castles(frame: Frame, occlusions=()) -> list[dict]:
    """Return fully visible, strongly matching sprites; coordinates are native."""
    # Policy paths often read the same observation more than once. Cache
    # immutable results only; callers always receive fresh dictionaries.
    records = _matches(frame.width, frame.height, bytes(frame.rgb), tuple(tuple(b) for b in occlusions))
    return [dict(record) for record in records]


@lru_cache(maxsize=2)
def _matches(width, height, rgb, occlusions):
    if width < WIDTH or height < HEIGHT or width > 512 or height > 448:
        return ()
    frame = Frame(width, height, rgb)
    # Every reference has >=192 dark outline pixels. A visible castle must
    # retain some even under its cursor; synthetic roof blocks need no scan.
    outline = near_bits(frame, (16, 16, 24), TOLERANCE)
    if outline.count(49) < 24:
        return ()
    colours = {p[2] for template in templates() for p in template.points}
    masks = {colour: (outline if colour == (16, 16, 24) else near_bits(frame, colour, TOLERANCE))
             for colour in colours}
    bits = {colour: int(mask, 2) for colour, mask in masks.items()}
    n = width * height
    hidden = bytearray(n)
    for x0, y0, x1, y1 in occlusions:
        x0, x1 = max(0, x0), min(width - 1, x1)
        if x0 <= x1:
            for y in range(max(0, y0), min(height - 1, y1) + 1):
                hidden[y * width + x0:y * width + x1 + 1] = b'\x01' * (x1 - x0 + 1)
    hidden_bits = int(hidden.translate(bytes.maketrans(b'\x00\x01', b'01')), 2)
    proposals = {colour: value | hidden_bits for colour, value in bits.items()}
    valid_row = ((1 << (width - WIDTH + 1)) - 1) << (WIDTH - 1)
    domain = sum(valid_row << (width * y) for y in range(HEIGHT - 1, height))
    found = []
    for template in templates():
        candidates = 0
        for a, b, c in zip(template.anchors[::3], template.anchors[1::3], template.anchors[2::3]):
            candidates |= ((proposals[a[2]] << (a[1] * width + a[0]))
                           & (proposals[b[2]] << (b[1] * width + b[0]))
                           & (proposals[c[2]] << (c[1] * width + c[0])))
        candidates &= domain
        if candidates.bit_count() > MAX_CANDIDATES:
            continue  # Flat palette blocks must not make verification unbounded.
        while candidates:
            bit = candidates & -candidates
            candidates ^= bit
            position = n - bit.bit_length()
            ox, oy = position % width, position // width
            visible = (template.points if not hidden_bits else tuple(
                (x, y, colour) for x, y, colour in template.points
                if not hidden[(oy + y) * width + ox + x]))
            if len(visible) * 100 < len(template.points) * 55:
                continue
            # Cheap rejection before counting every foreground pixel.
            probe = visible[::max(1, len(visible) // 48)]
            if sum(masks[c][(oy + y) * width + ox + x] == 49 for x, y, c in probe) * 100 < len(probe) * 88:
                continue
            correct = sum(masks[c][(oy + y) * width + ox + x] == 49 for x, y, c in visible)
            if correct * 100 < len(visible) * MIN_AGREEMENT:
                continue
            x0, y0, x1, y1 = template.box
            # All levels use the same 6x7 map-tile canvas. Cursor cell is
            # near its lower centre, independent of tower height or roof size.
            record = {'kind': template.kind, 'level': template.level,
                      'themes': template.themes, 'source': 'sprite',
                      'score': round(correct / len(visible), 4),
                      'box': (ox + x0, oy + y0, ox + x1, oy + y1),
                      'sprite_box': (ox, oy, ox + WIDTH - 1, oy + HEIGHT - 1),
                      'target': (ox + 24, oy + 40),
                      'clipped': (ox + x0 <= 1 or oy + y0 <= 1
                                  or ox + x1 >= width - 2 or oy + y1 >= height - 2)}
            # A complete large castle takes precedence over matching pieces
            # of its smaller towers. Disagreements cost four supporting pixels.
            found.append((correct - 4 * (len(visible) - correct), record))
    ranked, blocked = [], []
    for support, record in sorted(found, key=lambda pair: -pair[0]):
        rivals = [other for other_support, other in found
                  if abs(other_support - support) * 100 <= support * 5
                  and all(abs(other['sprite_box'][i] - record['sprite_box'][i]) <= 2 for i in (0, 1))]
        if any(other['kind'] != record['kind'] for other in rivals):
            blocked.append(record['sprite_box'][:2])
        themes = tuple(sorted({theme for other in rivals for theme in other['themes']}))
        record = {**record, 'themes': themes}
        levels = tuple(sorted({other['level'] for other in rivals}))
        if len(levels) > 1:
            record = {**record, 'level': None, 'level_candidates': levels}
        ranked.append(record)
    out = []
    for record in ranked:
        if any(all(abs(record['sprite_box'][i] - xy[i]) <= 2 for i in (0, 1)) for xy in blocked):
            continue
        if not any(_overlap(record['box'], existing['box']) for existing in out):
            out.append(record)
    return tuple(tuple(record.items()) for record in sorted(out, key=lambda r: (r['box'][1], r['box'][0])))


def merge_roofs(legacy, matched):
    """One observation per sprite; retain existing roof geometry when unique."""
    out = []
    for sprite in matched:
        pieces = [r for r in legacy if _overlap(r['box'], sprite['box'])]
        if (len(pieces) == 1 and pieces[0]['kind'] == sprite['kind']
                and abs(pieces[0]['target'][0] - sprite['target'][0]) <= 4
                and abs(pieces[0]['target'][1] - sprite['target'][1]) <= 8):
            roof = dict(pieces[0])
            roof.update({k: v for k, v in sprite.items() if k not in ('box', 'target', 'clipped')})
            roof['clipped'] = sprite['clipped'] or roof['clipped']
            out.append(roof)
        else:
            out.append(sprite)
    out.extend(r for r in legacy if not any(_overlap(r['box'], s['box']) for s in matched))
    return sorted(out, key=lambda r: (r['box'][1], r['box'][0]))
